import torch


def erfc(input_tensor: torch.Tensor) -> torch.Tensor:
    # torch.erfc is available in torch 1.10.0 (and torch.special.erfc exists
    # from 1.9 onward). Integer inputs are promoted to floating point first,
    # since the erfc kernel is not defined for integer dtypes.
    if not input_tensor.is_floating_point():
        input_tensor = input_tensor.to(torch.get_default_dtype())
    return torch.erfc(input_tensor)

