def build_interface():
    # Hide the download button and make the image non-interactive so the
    # user has no built-in way to save or share it. Gradio 3.36 has no
    # option to block right-click "Save image as...", so this is not
    # a hard guarantee.
    return gr.Interface(
        fn=display_image,
        inputs=None,
        outputs=gr.Image(
            show_label=False,
            show_download_button=False,
            interactive=False,
        ),
        allow_flagging="never",
        title="Image Viewer",
    )


if __name__ == "__main__":
    build_interface().launch()

