import pandas as pd
def get_grouped_df(df: pd.DataFrame) -> pd.DataFrame:
    keys = [c for c in df.columns if isinstance(df[c].dtype, pd.CategoricalDtype)]
    if not keys:
        keys = [df.columns[0]]
    grouped = df.groupby(keys, observed=False, dropna=False)
    result = grouped.size().to_frame("count")
    numeric = [c for c in df.select_dtypes("number").columns if c not in keys]
    if numeric:
        sums = grouped[numeric].sum(min_count=0)
        result = result.join(sums)
    return result.reset_index()

