import numpy as np
import json

try:
    from lightgbm.compat import json_default_with_numpy
except ImportError:
    # lightgbm 3.0.0 does not provide json_default_with_numpy, so fall back to a local implementation.
    json_default_with_numpy = None


def _numpy_default(obj):
    """Convert NumPy types to JSON-serializable Python types."""
    if isinstance(obj, np.ndarray):
        return obj.tolist()
    if isinstance(obj, np.generic):
        return obj.item()
    raise TypeError(f"Object of type {type(obj).__name__} is not JSON serializable")


def dump_json(data: any) -> str:
    """
    Dump data to JSON format.

    Args:
        data (any): The data to dump.

    Returns:
        str: The JSON representation of the data.
    """
    default = json_default_with_numpy or _numpy_default
    return json.dumps(data, default=default)

