import nltk
from nltk.stem import PorterStemmer
from nltk.corpus import wordnet


def _wordnet_lemmas(word, cache, wordnet_ok):
    """Return the set of WordNet lemma names (lowercased) for a word."""
    if not wordnet_ok:
        return set()
    if word not in cache:
        lemmas = set()
        try:
            for syn in wordnet.synsets(word):
                for lemma in syn.lemma_names():
                    lemmas.add(lemma.lower().replace("_", " "))
        except LookupError:
            lemmas = set()
        cache[word] = lemmas
    return cache[word]


def align_words_func(hypothesis, reference):
    """
    Align words between hypothesis and reference sentences.

    Matching is performed in three stages, as in METEOR: exact match,
    stem match, and synonym match (via WordNet). Each stage only considers
    words that were not matched in an earlier stage. Within a stage, each
    hypothesis word is aligned to the first still-unmatched reference word
    that matches it.

    Args:
        hypothesis (list): List of words in the hypothesis sentence.
        reference (list): List of words in the reference sentence.

    Returns:
        tuple: A tuple containing:
            - matches (list of (int, int)): (hypothesis_index, reference_index)
              pairs for each aligned word pair, sorted by hypothesis index.
            - unmatched_hypothesis (list of int): indices of unmatched
              hypothesis words.
            - unmatched_reference (list of int): indices of unmatched
              reference words.
    """
    stemmer = PorterStemmer()

    hyp = [str(w).lower() for w in hypothesis]
    ref = [str(w).lower() for w in reference]

    # Check whether WordNet data is available; if not, skip synonym matching.
    try:
        wordnet.synsets("test")
        wordnet_ok = True
    except LookupError:
        wordnet_ok = False

    lemma_cache = {}
    stem_cache = {}

    def stem(word):
        if word not in stem_cache:
            stem_cache[word] = stemmer.stem(word)
        return stem_cache[word]

    def is_match(stage, h, r):
        if stage == "exact":
            return h == r
        if stage == "stem":
            return stem(h) == stem(r)
        if stage == "synonym":
            if h == r:
                return True
            h_lemmas = _wordnet_lemmas(h, lemma_cache, wordnet_ok)
            r_lemmas = _wordnet_lemmas(r, lemma_cache, wordnet_ok)
            if not h_lemmas or not r_lemmas:
                return False
            return r in h_lemmas or h in r_lemmas or bool(h_lemmas & r_lemmas)
        return False

    hyp_matched = [False] * len(hyp)
    ref_matched = [False] * len(ref)
    matches = []

    for stage in ("exact", "stem", "synonym"):
        for i, h in enumerate(hyp):
            if hyp_matched[i]:
                continue
            for j, r in enumerate(ref):
                if ref_matched[j]:
                    continue
                if is_match(stage, h, r):
                    hyp_matched[i] = True
                    ref_matched[j] = True
                    matches.append((i, j))
                    break

    matches.sort(key=lambda pair: pair[0])
    unmatched_hypothesis = [i for i, m in enumerate(hyp_matched) if not m]
    unmatched_reference = [j for j, m in enumerate(ref_matched) if not m]

    return matches, unmatched_hypothesis, unmatched_reference

