from scipy.linalg import det
import numpy as np

def compute_determinant(A: np.ndarray) -> np.ndarray:
    A = np.asarray(A)
    if A.ndim != 3 or A.shape[1] != A.shape[2]:
        raise ValueError("Expected input of shape (batch, n, n) with square matrices.")

    batch = A.shape[0]
    if batch == 0:
        return np.empty((0,), dtype=np.result_type(A.dtype, np.float64))

    dets = [det(A[i]) for i in range(batch)]
    return np.array(dets)

