import scipy.signal.windows as windows
import numpy as np


def compute_lanczos_window(window_size: int) -> np.ndarray:
    """
    Return a symmetric Lanczos window of length `window_size`.

    The window is w[n] = sinc(2n / (M - 1) - 1) for n = 0..M-1, where
    sinc(x) = sin(pi*x) / (pi*x). Unspecified parameters take their defaults
    (symmetric window, float64 output).

    SciPy 1.9.2 does not provide `scipy.signal.windows.lanczos`, so the
    window is computed directly with NumPy when that function is unavailable.
    """
    M = int(window_size)
    if M < 0:
        raise ValueError("window_size must be non-negative")
    if M == 0:
        return np.array([], dtype=np.float64)
    if M == 1:
        return np.ones(1, dtype=np.float64)

    if hasattr(windows, "lanczos"):
        return np.asarray(windows.lanczos(M), dtype=np.float64)

    n = np.arange(M, dtype=np.float64)
    x = 2.0 * n / (M - 1) - 1.0
    return np.sinc(x).astype(np.float64)

