import warnings
from scipy.linalg import det
import numpy as np
warnings.filterwarnings('error')

def check_invertibility(matrices : np.ndarray) -> np.bool_:
    M = np.asarray(matrices)
    if M.ndim < 2 or M.shape[-1] != M.shape[-2]:
        return np.bool_(False)
    n = M.shape[-1]
    if n == 0:
        return np.bool_(True)
    for idx in np.ndindex(M.shape[:-2]):
        A = M[idx]
        try:
            d = det(A)
            ok = bool(np.isfinite(d) and d != 0)
        except Exception:
            try:
                ok = bool(np.linalg.matrix_rank(A) == n)
            except Exception:
                ok = False
        if not ok:
            return np.bool_(False)
    return np.bool_(True)

