from sympy import *

def custom_check_carmichael(n: int) -> bool:
    # Korselt's criterion: n is a Carmichael number iff n is composite,
    # squarefree, and (p - 1) divides (n - 1) for every prime p dividing n.
    if n < 2:
        return False
    if isprime(n):
        return False
    factors = factorint(n)
    if len(factors) < 2:
        return False
    for p, e in factors.items():
        if e > 1:
            return False
        if (n - 1) % (p - 1) != 0:
            return False
    return True

