import inspect

from falcon.routing import map_http_methods


class CustomRouter:
    def __init__(self):
        self.routes = {}


def solution() -> None:

    def add_route(self, uri_template, resource, **kwargs):
        method_map_kwargs = {}
        if 'fallback' in kwargs:
            # Falcon 2.0.0's map_http_methods(resource, suffix=None) has no
            # 'fallback' parameter, so forward it only when it is accepted.
            accepted = inspect.signature(map_http_methods).parameters
            if 'fallback' in accepted:
                method_map_kwargs['fallback'] = kwargs['fallback']

        method_map = map_http_methods(resource, **method_map_kwargs)
        self.routes[uri_template] = (resource, method_map)
        return method_map

    CustomRouter.add_route = add_route

