import scipy.signal.windows as windows
import numpy as np


def compute_lanczos_window(window_size: int) -> np.ndarray:
    # scipy.signal.windows.lanczos is not available in SciPy 1.9.2, so the
    # window is computed directly from its definition, using the default
    # symmetric form (sym=True):
    #   w[n] = sinc(2n / (M - 1) - 1),  n = 0, ..., M - 1
    # numpy.sinc uses the normalized definition sin(pi x) / (pi x).
    M = int(window_size)
    if M < 0:
        raise ValueError("window_size must be non-negative")
    if M == 0:
        return np.array([], dtype=np.float64)
    if M == 1:
        return np.ones(1, dtype=np.float64)

    n = np.arange(M, dtype=np.float64)
    return np.sinc(2.0 * n / (M - 1) - 1.0)

