import numpy as np
from scipy.signal import hilbert

def compute_hilbert_transform(a: np.ndarray, b: np.ndarray, dtype=np.float64) -> np.ndarray:
    # compute_hilbert_transform should return the Hilbert transform of the
    # a and b arrays stacked vertically, with safe casting and the specified
    # dtype.
    # raise TypeError if needed

    a = np.asarray(a)
    b = np.asarray(b)

    # Inputs must be real numeric arrays.
    for arr in (a, b):
        if not np.issubdtype(arr.dtype, np.number) or np.iscomplexobj(arr):
            raise TypeError(
                f"Inputs must be real numeric arrays, got dtype {arr.dtype}"
            )

    try:
        out_dtype = np.dtype(dtype)
    except TypeError as exc:
        raise TypeError(f"Invalid dtype: {dtype!r}") from exc

    if not (np.issubdtype(out_dtype, np.floating)
            or np.issubdtype(out_dtype, np.complexfloating)):
        raise TypeError(
            f"dtype must be a real or complex floating type, got {out_dtype}"
        )

    # Vertical stacking (raises ValueError on incompatible shapes).
    stacked = np.vstack((a, b))

    # Safe cast of the stacked input to float64 for the computation.
    if not np.can_cast(stacked.dtype, np.float64, casting="safe"):
        raise TypeError(
            f"Cannot safely cast input dtype {stacked.dtype} to float64"
        )
    x = stacked.astype(np.float64, casting="safe")

    # Analytic signal along the last axis; its imaginary part is the
    # Hilbert transform of each row.
    analytic = hilbert(x, axis=-1)

    if np.issubdtype(out_dtype, np.complexfloating):
        result = analytic
    else:
        result = np.imag(analytic)

    # Only allow casts that keep the numeric kind (no silent complex->real).
    if not np.can_cast(result.dtype, out_dtype, casting="same_kind"):
        raise TypeError(
            f"Cannot cast result dtype {result.dtype} to {out_dtype} safely"
        )

    return result.astype(out_dtype, casting="same_kind")

