import sympy

def custom_bottom_up(expr: sympy.Expr) -> int:
    # Lambda applied to each node after its children have been processed.
    # Here it counts the nodes in the expression tree.
    combine = lambda node, child_results: 1 + sum(child_results)

    def _visit(node):
        children = getattr(node, "args", ())
        child_results = [_visit(child) for child in children]
        return combine(node, child_results)

    return int(_visit(sympy.sympify(expr)))

