import sympy

def custom_array_to_matrix(array: sympy.Array) -> sympy.Matrix:
    from sympy.tensor.array import NDimArray

    if not isinstance(array, NDimArray):
        array = Array(array)

    rank = array.rank()
    if rank == 0:
        raise ValueError("A scalar (rank-0) array cannot be converted to a matrix.")
    if rank > 2:
        raise ValueError(f"Only rank-1 or rank-2 arrays can be converted, got rank {rank}.")

    # Rank-1 arrays become column vectors; rank-2 arrays become m x n matrices.
    return Matrix(array.tolist())

